.hyp-st-group {
    display: flex !important;
    gap: 4px !important;
    align-items: center !important;
    background: var(--trk-input-bg) !important;
    padding: 3px 6px !important;
    border-radius: 8px !important;
    border: 1px solid var(--trk-input-border) !important;
}
.hyp-st-btn {
    background: transparent !important;
    border: 1px solid transparent !important;
    font-size: 1.1rem !important;
    line-height: 1 !important;
    padding: 2px 6px !important;
    border-radius: 6px !important;
    cursor: pointer !important;
    opacity: 0.4 !important;
    transition: all 0.15s !important;
}
.hyp-st-btn:hover { opacity: 0.8 !important; background: rgba(128,128,128,0.1) !important; }
.hyp-st-btn.active { opacity: 1 !important; background: rgba(128,128,128,0.2) !important; }

.hyp-st-btn.planned.active { background: rgba(149,165,166,0.25) !important; color: #566573 !important; }
.hyp-st-btn.in_progress.active { background: rgba(52,152,219,0.25) !important; color: #1565c0 !important; }
.hyp-st-btn.done.active { background: rgba(46,204,113,0.25) !important; color: #1b5e20 !important; }
.hyp-st-btn.failed.active { background: rgba(231,76,60,0.25) !important; color: #b71c1c !important; }

.hyp-fields:has(.hyp-st-btn.done.active) input[type="text"].hyp-fld[data-k="title"] {
    text-decoration: line-through !important;
    opacity: 0.6 !important;
}

.hyp-fields.hyp-overdue {
    border-left: 4px solid #e74c3c !important;
    background: rgba(231,76,60,0.05) !important;
    padding-left: 10px !important;
    border-radius: 4px !important;
}
.hyp-overdue input[type="text"].hyp-fld[data-k="title"] {
    color: #e74c3c !important;
}

.hyp-badge {
    background: rgba(109,194,240,0.15) !important;
    color: #6dc2f0 !important;
    border: 1px solid rgba(109,194,240,0.3) !important;
}
.hyp-badge-done {
    background: rgba(46,204,113,0.18) !important;
    color: #2ecc71 !important;
    border-color: rgba(46,204,113,0.35) !important;
}
.hyp-badge-progress {
    background: rgba(241,196,15,0.18) !important;
    color: #b7950b !important;
    border-color: rgba(241,196,15,0.35) !important;
}
body.trk-theme-light .hyp-badge { background: rgba(2,119,189,0.1); color: #01579b; border-color: rgba(2,119,189,0.25); }
body.trk-theme-light .hyp-badge-done { background: rgba(46,125,50,0.12); color: #2e7d32; border-color: rgba(46,125,50,0.3); }
body.trk-theme-light .hyp-badge-progress { background: rgba(230,168,26,0.15); color: #8a6300; border-color: rgba(230,168,26,0.35); }
